+/**
+ * Applies the loyalty discount at checkout time.
+ */
+function applyPromotion(basePriceCents, customerTier) {
+  const tierPercent = customerTier === 'gold' ? 0.15 : customerTier === 'silver' ? 0.08 : 0;
+  return Math.floor(basePriceCents * (1 - tierPercent));
+}
+
+module.exports = { applyPromotion };

